// Prepare prompt and image data for Gemini Vision
const body = $input.first().json.body || $input.first().json;
const base64Image = body.imageBase64 || body.image || '';
const mimeType = body.mimeType || 'image/jpeg';
const userNotes = body.notes || body.text || '';

const prompt = `Anda adalah seorang ahli gizi (clinical nutritionist) dan pakar kuliner nusantara dan internasional.
Tugas Anda adalah menganalisis foto makanan atau deskripsi makanan berikut untuk fitur Calorie Tracker di aplikasi LifeSync.

Catatan tambahan dari user: "${userNotes}"

Instruksi:
1. Identifikasi semua komponen makanan dalam piring/kemasan.
2. Berikan estimasi porsi (gram/ukuran rumah tangga), total kalori (kkal), protein (g), karbohidrat (g), dan lemak (g).
3. Berikan rincian (breakdown) per item makanan.
4. Output WAJIB berupa JSON murni tanpa markdown, tanpa backtick, dengan format:
{
  "foodName": "Nama makanan utama ringkas",
  "calories": 600,
  "proteins": 25.0,
  "carbohydrates": 70.0,
  "fat": 20.0,
  "servingSize": "1 porsi",
  "servings": 1,
  "confidence": "high" | "medium" | "low",
  "breakdown": [
    {
      "item": "Nama item",
      "portion": "100g",
      "calories": 200,
      "proteins": 5.0,
      "carbohydrates": 40.0,
      "fat": 2.0
    }
  ],
  "notes": "Saran nutrisi singkat (contoh: tinggi protein, kontrol porsi karbo)"
}`;

const parts = [{ text: prompt }];

if (base64Image) {
  // Clean base64 string if data URI scheme was included
  const cleanBase64 = base64Image.replace(/^data:image\/\w+;base64,/, '');
  parts.push({
    inlineData: {
      mimeType: mimeType,
      data: cleanBase64
    }
  });
}

return {
  json: {
    contents: [
      {
        parts: parts
      }
    ],
    generationConfig: {
      temperature: 0.2,
      responseMimeType: "application/json"
    }
  }
};

try {
  const response = $input.first().json;
  const candidate = response.candidates?.[0];
  const text = candidate?.content?.parts?.[0]?.text || '{}';

  // Parse JSON from text
  const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
  const parsedData = JSON.parse(cleanText);

  return {
    json: {
      success: true,
      data: parsedData
    }
  };
} catch (err) {
  return {
    json: {
      success: false,
      error: err.message || 'Gagal memproses analisis nutrisi dari Gemini',
      raw: $input.first().json
    }
  };
}
